import type { Event } from "@sentry/nextjs";

/**
 * RC37-V — fail-closed privacy policy for initial QA Sentry enablement.
 *
 * Sentry events can contain credentials / PHI in arbitrary fields, exception
 * messages, stack frames, URLs, breadcrumbs or request context. Redacting
 * named keys is not enough to guarantee safety. Until a reviewed diagnostic
 * schema exists, send only fixed, non-user-provided metadata.
 *
 * The event ID and timestamp are generated by the SDK. We intentionally do
 * not copy any untrusted event fields, including event.message and tags.
 */
export function sanitizeSentryEvent(event: Event): Event {
  return {
    ...(typeof event.event_id === "string" &&
    /^[a-fA-F0-9]{32}$/.test(event.event_id)
      ? { event_id: event.event_id }
      : {}),
    ...(typeof event.timestamp === "number" &&
    Number.isFinite(event.timestamp)
      ? { timestamp: event.timestamp }
      : {}),
    level: "error",
    message: "HeyDoctor QA sanitized diagnostic event",
    fingerprint: ["heydoctor-qa-redacted-event"],
    tags: { privacy: "strict-redaction", source: "heydoctor-web-qa" },
  };
}
